# [LATER-STEP] localized_audio_preview.py – Generate spoken previews of translated copy\n# Uses ElevenLabs Text to Speech (concrete provider)\nimport os\nimport requests\nfrom typing import Dict\n\n# Provider‑specific signal\nELEVENLABS_API_KEY = os.getenv('ELEVENLABS_API_KEY')\nif not ELEVENLABS_API_KEY:\n    raise RuntimeError('Set ELEVENLABS_API_KEY environment variable with ElevenLabs API key.')\n\nBASE_URL = 'https://voice-clone-prod-api.elevenlabs.io/v1/text-to-speech'\n\nHEADERS = {\n    'xi-api-key': ELEVENLABS_API_KEY,\n    'Content-Type': 'application/json',\n}\n\ndef generate_audio(text: str, voice_id: str = '0') -> Dict[str, Any]:\n    \"\"\"Generate an audio preview for the given translated text.\n\n    Returns a dict containing the audio binary (base64) and metadata.\n    \"\"\"\n    payload = {\n        'text': text,\n        'voice_settings': {\n            'stability': 0.75,\n            'similarity_boost': 0.85,\n        },\n    }\n    resp = requests.post(BASE_URL, headers=HEADERS, json=payload)\n    resp.raise_for_status()\n    return resp.json()\n\n# Example usage\nif __name__ == '__main__':\n    translated = 'Hello world!'\n    audio_info = generate_audio(translated, voice_id='104691')  # example voice ID\n    print('Audio metadata:', audio_info)